class History {
  // done = applied stack; undone = redo stack. Two stacks model a linear timeline.
  constructor() { this.done = []; this.undone = []; }
  // A fresh action invalidates redo — branching destroys the old future.
  do(cmd) { cmd.apply(); this.done.push(cmd); this.undone = []; }
  // No-op on empty stack — don't throw; UI buttons just stay disabled.
  undo() { const c = this.done.pop(); if (!c) return; c.revert(); this.undone.push(c); }
  redo() { const c = this.undone.pop(); if (!c) return; c.apply(); this.done.push(c); }
}
let x = 0;
const h = new History();
const add = n => ({ apply: () => x += n, revert: () => x -= n });
h.do(add(1));
console.log(x);
h.do(add(2));
console.log(x);
h.undo();
console.log(x);
h.do(add(10));
console.log(x);
h.undo();
console.log(x);
h.undo();
console.log(x);
